 class Ledger:
     def __init__(self):
         self._stock = {}
+        self._history = []

     def add(self, sku, qty):
         if qty <= 0:
             raise ValueError("qty to add must be positive")
         self._stock[sku] = self._stock.get(sku, 0) + qty
+        self._history.append(("add", sku, qty))

     def remove(self, sku, qty):
         if qty <= 0:
@@ -16,9 +18,14 @@ class Ledger:
         if qty > self._stock.get(sku, 0):
             raise ValueError("cannot remove more than in stock")
         self._stock[sku] -= qty
+        self._history.append(("remove", sku, qty))

     def quantity(self, sku):
         return self._stock.get(sku, 0)

     def skus(self):
         return sorted(self._stock)
+
+
+    def history(self):
+        return list(self._history)
